 const ol=card.querySelector('.am-steps');for(const [icon,i] of STEPS[mode]||[]){const li=document.createElement('li');li.innerHTML=ICON[icon]+'<span></span>';li.querySelector('span').textContent=I.steps[mode][i];ol.append(li)}
