// The opaque Arena owns its own RAF/physics. Do not also step and render the
// covered native scene (including its WebGL framebuffer) behind this canvas.
// Guard this game instance only; never mutate pause/timeScale or scene state.
function ownNativeRendering(game){
 const stack=game?.getSceneStack();if(!stack)return;
 const covered=()=>root&&!root.hidden;
 for(const method of ['step','renderWithoutStep']){
  const original=stack[method];
  if(typeof original!=='function')continue;
  const guarded=function(){return covered()?true:original.apply(this,arguments)};
  stack[method]=guarded;
  window.addEventListener('pagehide',e=>{if(!e.persisted&&stack[method]===guarded)stack[method]=original});
 }
}
function install(){if(nativeOpen)return true;menu=window.PirateMenuV2;if(!menu?.state?.ready)return false;ownNativeRendering(menu.g);nativeOpen=menu.openArena;const visible=menu.isVisible;menu.isVisible=function(){return root&&!root.hidden||document.getElementById('pirate-arena-friend')?false:visible.call(this)};menu.toggleArena=()=>open();const back=window.__pfBack;window.__pfBack=()=>root&&!root.hidden?(model?pause():close(),true):back?.()||false;return true}
let installTimer;
if(!install())installTimer=setInterval(()=>{if(install())clearInterval(installTimer)},250);
window.addEventListener('pagehide',e=>{if(!e.persisted)clearInterval(installTimer);stop()});
// pagehide stops audio/network/RAF. A restored document must expose a usable
// lobby rather than the old match canvas whose simulation has been disposed.
window.addEventListener('pageshow',e=>{if(e.persisted&&root&&!root.hidden)open()});
